/**
 * Catalog renderEntry for kinds not yet registered as EntityKindModules.
 * Moves onto each kind's CatalogFacet when its module lands.
 */
import { asNamedRef, namedFactoryEntry, } from "../catalog/render-helpers.js";
/** Simple `{ name }` / optional parent for deferred catalog stubs. */
export function renderDeferredNamedEntry(factoryName, opts) {
    return (args) => {
        const named = asNamedRef(args.ref);
        return namedFactoryEntry({
            factoryName,
            keyName: args.keyName,
            baseIndent: args.baseIndent,
            name: named.name,
            parent: opts?.omitParent === true ? undefined : named.parent,
        });
    };
}
